import numpy as np
from vispy import app, gloo
from vispy.util.transforms import ortho

# Vertex shader
vertex_shader = """
#version 120

attribute vec2 a_position;
attribute vec2 a_velocity;
attribute float a_lifetime;
attribute float a_size;
attribute vec4 a_color;

uniform float u_time;
uniform float u_duration;
uniform mat4 u_projection;

varying float v_lifetime;
varying vec4 v_color;
varying vec2 v_position;

void main() {
    // Calculate normalized lifetime (0.0 to 1.0)
    float norm_lifetime = a_lifetime / u_duration;

    // Apply velocity over time
    vec2 position = a_position + a_velocity * u_time;

    // Apply size variation based on lifetime
    float size = a_size * (1.0 - norm_lifetime);

    // Fade out particles as they age
    float alpha = 1.0 - norm_lifetime;
    v_color = vec4(a_color.rgb, a_color.a * alpha);

    // Set varying values
    v_lifetime = norm_lifetime;
    v_position = position;

    // Transform position
    gl_Position = u_projection * vec4(position, 0.0, 1.0);
}
"""

# Fragment shader
fragment_shader = """
#version 120

varying float v_lifetime;
varying vec4 v_color;
varying vec2 v_position;

void main() {
    // Create circular particle shape
    vec2 center = vec2(0.0, 0.0);
    float dist = distance(gl_PointCoord, center);

    // Only draw within circle
    if (dist > 0.5) {
        discard;
    }

    // Apply color
    gl_FragColor = v_color;
}
"""

class Canvas(app.Canvas):
    def __init__(self):
        super().__init__(size=(800, 600), title='Fireworks Simulation')

        # Initialize OpenGL context
        self._program = gloo.Program(vertex_shader, fragment_shader)

        # Create initial VBOs
        self._create_buffers()

        # Simulation parameters
        self._duration = 1.0  # seconds
        self._explosion_count = 0
        self._time = 0.0

        # Set up projection matrix
        self._projection = ortho(-400, 400, -300, 300, -1, 1)
        self._program['u_projection'] = self._projection

        # Start timer
        self.timer = app.Timer('auto', connect=self._on_timer, start=True)

        # Create first explosion
        self._create_explosion(0, 0)

        # Enable blending for transparency
        gloo.set_state(blend=True, blend_func=('src_alpha', 'one_minus_src_alpha'))

    def _create_buffers(self):
        """Create and initialize vertex buffer objects"""
        # Create initial data arrays
        self._max_particles = 10000
        self._particle_data = np.zeros(self._max_particles, dtype=[
            ('a_position', np.float32, 2),
            ('a_velocity', np.float32, 2),
            ('a_lifetime', np.float32),
            ('a_size', np.float32),
            ('a_color', np.float32, 4)
        ])

        # Create VBO
        self._vbo = gloo.VertexBuffer(self._particle_data)
        self._program.bind(self._vbo)

        # Set attributes
        self._program['a_position'] = self._particle_data['a_position']
        self._program['a_velocity'] = self._particle_data['a_velocity']
        self._program['a_lifetime'] = self._particle_data['a_lifetime']
        self._program['a_size'] = self._particle_data['a_size']
        self._program['a_color'] = self._particle_data['a_color']

    def _create_explosion(self, x, y):
        """Create a new explosion at given coordinates"""
        # Find available slots in particle array
        start_idx = self._explosion_count * 100
        end_idx = min(start_idx + 100, self._max_particles)

        # Create explosion parameters
        num_particles = end_idx - start_idx
        colors = [
            [1.0, 0.0, 0.0, 1.0],  # Red
            [0.0, 1.0, 0.0, 1.0],  # Green
            [0.0, 0.0, 1.0, 1.0],  # Blue
            [1.0, 1.0, 0.0, 1.0],  # Yellow
            [1.0, 0.0, 1.0, 1.0],  # Magenta
            [0.0, 1.0, 1.0, 1.0],  # Cyan
            [1.0, 0.5, 0.0, 1.0],  # Orange
        ]

        # Randomize explosion properties
        color_idx = np.random.randint(0, len(colors))
        color = colors[color_idx]

        # Create particles for this explosion
        for i in range(start_idx, end_idx):
            # Position around explosion center
            angle = np.random.uniform(0, 2 * np.pi)
            distance = np.random.uniform(0, 50)
            self._particle_data[i]['a_position'] = [
                x + distance * np.cos(angle),
                y + distance * np.sin(angle)
            ]

            # Random velocity
            speed = np.random.uniform(50, 200)
            self._particle_data[i]['a_velocity'] = [
