    ax.set_xlabel('Sample Number')
    ax.set_ylabel('CPU Usage (%)')
    ax.grid(True, alpha=0.3)

    # Apply colormap to background
    ax.set_facecolor('white')

    # Hide ticks
    hide_ticks(ax)

    plt.tight_layout()
    return fig

def create_table_data(cpu_data, num_rows=20):
    """Create pandas DataFrame for table display"""
    if not PANDAS_AVAILABLE or len(cpu_data) == 0:
        return None

    # Take last num_rows entries
    recent_data = cpu_data[-num_rows:]

    # Create DataFrame
    df = pd.DataFrame({
        'Sample': list(range(len(cpu_data) - len(recent_data), len(cpu_data))),
        'CPU_Usage (%)': [round(val, 2) for val in recent_data]
    })

    return df

def update_cpu_history():
    """Update the CPU usage history"""
    global cpu_history, frozen

    if frozen:
        return

    cpu_usage = get_cpu_usage()
    cpu_history.append(cpu_usage)

    # Keep only sample_count entries
    if len(cpu_history) > sample_count:
        cpu_history = cpu_history[-sample_count:]

