                ui.input_action_button("clear", "Clear History", class_="btn-danger"),
                ui.input_action_button("freeze", "Freeze Output", class_="btn-warning"),
                ui.input_action_button("unfreeze", "Unfreeze Output", class_="btn-success")
            ),
            ui.column(8,
                ui.output_plot("cpu_plot")
            )
        ),

