from psyclone.transformations import TransformationError

# Boolean variables to control transformation application
apply_redundant_computation = True
apply_async_halo_exchanges = True
apply_openmp_colouring = True
apply_intrinsic_inlining = True

def apply_transformations(psy):
    """
    Apply a series of transformations to the given psy object.

    :param psy: The psy object to transform
    :return: The transformed psy object
    """
    try:
        # Get all invokes from the psy object
        invokes = psy.invokes

        # Apply transformations based on boolean flags
        if apply_redundant_computation:
            redundant_trans = RedundantComputationTrans()
            for invoke in invokes:
                redundant_trans.apply(invoke)

