import sys
import time
from bcc import BPF
from ctypes import c_ulonglong

# BPF program code
bpf_code = """
#include <uapi/linux/ptrace.h>
#include <linux/sched.h>

// Structure to hold function addresses
struct addr_t {
    u64 resolver_addr;
    u64 impl_addr;
};

// Map to store histogram of strlen return values
BPF_HISTOGRAM(str_len_hist);

// Map to store function addresses
BPF_ARRAY(addr_map, struct addr_t, 1);

// Counter for total calls
BPF_ARRAY(call_count, u64, 1);

// Function to count return values
int count_strlen_ret(struct pt_regs *ctx) {
    // Get the return value (length)
    long ret = PT_REGS_RC(ctx);

    // Only count positive lengths
    if (ret >= 0) {
        // Increment histogram bin
        u64 key = ret;
        str_len_hist.increment(key);

        // Increment call counter
        u64 *count = call_count.lookup(&key);
        if (count) {
            (*count)++;
        }
    }

    return 0;
}

// Function to submit addresses
int submit_addrs(struct pt_regs *ctx) {
    // This will be attached to the resolver function
    struct addr_t addr_data = {};
    addr_data.resolver_addr = (u64)PT_REGS_IP(ctx);

    // Store in map
    int idx = 0;
    addr_map.update(&idx, &addr_data);

    return 0;
}
"""

def get_symbol_address(symbol):
    """Get the address of a symbol from /proc/kallsyms"""
    try:
        with open('/proc/kallsyms', 'r') as f:
            for line in f:
                parts = line.strip().split()
                if len(parts) >= 3 and parts[2] == symbol:
