        outfile = open(self.save_name, "w")

        prefix = ""
        for line in l:
            outfile.write(prefix + line)
            prefix = "\n"

def re_tab(s):
    ""
    l = []
    p = 0
    for i in range(8, len(s), 8):
        if s[i-2:i] == "  ":

            l.append(f"{s[p:i].rstrip()}\t")
            p = i

    if p == 0:
        return s
    else:
        l.append(s[p:])
        return "".join(l)

