import urwid
import os

class LazyTextWalker(urwid.ListWalker):
    """Custom ListWalker for lazy loading of text file content."""

    def __init__(self, filename):
        self.filename = filename
        self.lines = []
        self.focus = 0
        self._load_file()

    def _load_file(self):
        """Load file content lazily."""
        if not os.path.exists(self.filename):
            # Create empty file if it doesn't exist
            with open(self.filename, 'w') as f:
                pass

        try:
            with open(self.filename, 'r') as f:
                self.lines = [line.rstrip('\n') for line in f.readlines()]
        except Exception:
            # If we can't read the file, start with empty lines
            self.lines = ['']

        # Ensure at least one line exists
        if not self.lines:
            self.lines = ['']

    def get_focus(self):
        """Get the currently focused item."""
        if not self.lines:
            return None, self.focus
        return self._get_item(self.focus)

    def set_focus(self, position):
        """Set the focus to a specific position."""
        self.focus = max(0, min(position, len(self.lines) - 1))
        self._modified()

    def get_next(self, position):
        """Get the next item after the given position."""
        if position + 1 >= len(self.lines):
            return None, None
        return self._get_item(position + 1)

    def get_prev(self, position):
        """Get the previous item before the given position."""
        if position <= 0:
            return None, None
        return self._get_item(position - 1)

    def _get_item(self, position):
        """Get item at position."""
        if position < 0 or position >= len(self.lines):
            return None, None
        return urwid.Text(self.lines[position]), position

    def insert_line(self, position, content=''):
        """Insert a new line at position."""
        self.lines.insert(position, content)
        self.set_focus(position)
        self._modified()

    def delete_line(self, position):
        """Delete line at position."""
        if len(self.lines) <= 1:
            return
        del self.lines[position]
        self.set_focus(max(0, position - 1))
        self._modified()

    def set_line_content(self, position, content):
        """Set content of line at position."""
        if 0 <= position < len(self.lines):
            self.lines[position] = content
            self._modified()

    def get_line_content(self, position):
        """Get content of line at position."""
        if 0 <= position < len(self.lines):
            return self.lines[position]
        return ''

    def save_to_file(self, filename):
        """Save all lines to file."""
        with open(filename, 'w') as f:
            for i, line in enumerate(self.lines):
                if i < len(self.lines) - 1:
                    f.write(line + '\n')
                else:
                    f.write(line)

class TextEditor(urwid.WidgetWrap):
    """Main text editor widget."""

    def __init__(self, filename):
        self.filename = filename
        self.walker = LazyTextWalker(filename)
        self.listbox = urwid.ListBox(self.walker)

        # Footer with instructions
        self.footer = urwid.Text([
            "Ctrl+S: Save | Ctrl+Q: Quit | ",
            ("key", "Enter"), " New Line | ",
            ("key", "Backspace"), " Delete Char | ",
            ("key", "Del"), " Delete Line | ",
            ("key", "↑↓"), " Navigate Lines"
        ])

        # Main layout
        self.frame = urwid.Frame(
            body=self.listbox,
            footer=self.footer
        )

        super().__init__(self.frame)

    def keypress(self, size, key):
        """Handle keypress events."""
        # Get current cursor position
        focus_pos = self.walker.focus

        # Get current line content
        current_line = self.walker.get_line_content(focus_pos)

        # Handle special keys
        if key == 'enter':
            # Insert new line after current line
            self.walker.insert_line(focus_pos + 1, '')
            return None

        elif key == 'backspace':
            # Handle backspace at beginning of line
            if focus_pos > 0 and len(current_line) == 0:
                # Delete empty line and move up
                self.walker.delete_line(focus_pos)
                return None
            elif len(current_line) > 0:
                # Delete character from current line
                new_content = current_line[:-1]
                self.walker.set_line_content(focus_pos, new_content)
                return None

        elif key == 'delete':
            # Delete current line if it's empty or delete entire line
            if len(current_line) == 0 and len(self.walker.lines) > 1:
                self.walker.delete_line(focus_pos)
                return None
            else:
                # Clear current line content
                self.walker.set_line_content(focus_pos, '')
                return None

        elif key == 'ctrl s':
            # Save file
            self.walker.save_to_file(self.filename)
            self.footer.set_text("File saved successfully!")
            return None

        elif key == 'ctrl q':
            # Quit application
            raise urwid.ExitMainLoop()

        elif key == 'up':
            # Move up one line
            if focus_pos > 0:
                self.walker.set_focus(focus_pos - 1)
                return None

        elif key == 'down':
            # Move down one line
            if focus_pos < len(self.walker.lines) - 1:
                self.walker.set_focus(focus_pos + 1)
                return None

        elif key == 'left':
            # Move left (handled by ListBox)
            return super().keypress(size, key)

        elif key == 'right':
            # Move right (handled by ListBox)
            return super().keypress(size, key)

        # For regular text input, let the ListBox handle it
        return super().keypress(size, key)

def main(filename):
    """Main function to run the text editor."""
    # Check if file exists
    if not os.path.exists(filename):
        print(f"Warning: File '{filename}' does not exist. Creating new file.")

    # Create and run the editor
    editor = TextEditor(filename)
    palette = [
        ('body', 'black', 'light gray'),
        ('focus', 'white', 'dark blue'),
        ('key', 'light cyan', 'dark blue'),
        ('footer', 'light gray', 'dark blue'),
    ]

    loop = urwid.MainLoop(editor, palette)
    try:
        loop.run()
    except KeyboardInterrupt:
        print("\nEditor exited.")

