            # Set slider2 to be half of slider1
            session.update_slider("slider2", value=input.slider1() // 2)

    # Update numeric2 based on numeric1
    @session.effect
    def _update_numeric2():
        if input.numeric1() is not None:
            # Set numeric2 to be twice numeric1
            session.update_numeric("numeric2", value=input.numeric1() * 2)

    # Update slider2 when numeric1 changes
    @session.effect
    def _update_slider2_from_numeric():
        if input.numeric1() is not None:
            # Set slider2 to be 10% of numeric1
            session.update_slider("slider2", value=int(input.numeric1() * 0.1))

    # Update text input based on slider1
    @session.effect
    def _update_text_input():
        if input.slider1() is not None:
            session.update_text("text_input", value=f"Slider Value: {input.slider1()}")

# Create the app
app = App(app_ui, server)

# Run the app in debug mode
if __name__ == "__main__":
    app.run(debug=True)
